package scoring

import (
	"encoding/json"
	"os"
	"testing"
)

// TestUpstreamGolden compares TaskScore with task_score of CMS on random
// submissions (testdata/upstream_golden.json, generated by
// testdata/gen_golden.py): every score mode and view, ties in the
// timestamps, unofficial and unscored submissions, compilation errors and
// details of every shape.
func TestUpstreamGolden(t *testing.T) {
	b, err := os.ReadFile("testdata/upstream_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Submissions []struct {
			Timestamp int  `json:"timestamp"`
			Official  bool `json:"official"`
			Tokened   bool `json:"tokened"`
			Result    *struct {
				Scored             bool            `json:"scored"`
				Score              float64         `json:"score"`
				ScoreDetails       json.RawMessage `json:"score_details"`
				PublicScore        float64         `json:"public_score"`
				PublicScoreDetails json.RawMessage `json:"public_score_details"`
			} `json:"result"`
		} `json:"submissions"`
		ScoreMode      string `json:"score_mode"`
		ScorePrecision int    `json:"score_precision"`
		Full           [2]any `json:"full"`
		Public         [2]any `json:"public"`
		OnlyTokened    [2]any `json:"only_tokened"`
	}
	if err := json.Unmarshal(b, &cases); err != nil {
		t.Fatal(err)
	}
	if len(cases) < 100 {
		t.Fatalf("only %d cases", len(cases))
	}
	for i, c := range cases {
		var subs []Submission
		for _, s := range c.Submissions {
			sub := Submission{Timestamp: at(s.Timestamp), Unofficial: !s.Official, Tokened: s.Tokened}
			if r := s.Result; r != nil && r.Scored {
				sub.Scored = true
				sub.Score, sub.ScoreDetails = r.Score, r.ScoreDetails
				sub.PublicScore, sub.PublicScoreDetails = r.PublicScore, r.PublicScoreDetails
			}
			subs = append(subs, sub)
		}
		for _, v := range []struct {
			view View
			want [2]any
		}{{Full, c.Full}, {Public, c.Public}, {OnlyTokened, c.OnlyTokened}} {
			score, partial, err := TaskScore(subs, c.ScoreMode, c.ScorePrecision, v.view)
			if err != nil {
				t.Fatal(err)
			}
			if score != v.want[0].(float64) || partial != v.want[1].(bool) {
				t.Errorf("case %d (%s, view %d): got (%v, %v), want %v", i, c.ScoreMode, v.view, score, partial, v.want)
			}
		}
	}
}
